/bin/bash -lc "python - <<'PY'
from qutebrowser.qt.core import QUrl
u=QUrl('http://example.com/%3A5?x=%33&y=7#%3A10')
for name in ('host','path','query','fragment'):
 f=getattr(u,name)
 for mode in (QUrl.FullyEncoded,QUrl.FullyDecoded,QUrl.PrettyDecoded):
  try: print(name,mode,f(mode))
  except Exception as e: print(type(e).__name__,str(e))
PY"

