/bin/bash -lc "python - <<'PY'
from PyQt5.QtCore import QUrl
for setter in ['setPath','setQuery','setFragment','setHost']:
 u=QUrl('http://example.com/%3A?x=%3A#%3A')
 v={'setPath':'/%3A6','setQuery':'x=%3A6','setFragment':'%3A6','setHost':'foo%3A6.com'}[setter]
 try: getattr(u,setter)(v); print(setter,u.toString(QUrl.FullyEncoded))
 except Exception as e: print(setter,repr(e))
PY"

